// Generated by `factory render`. Do not edit.
// Pinned downloads for static analysis, with only Node's own modules (the generated CI script copies this file):
//   installBinary  a release asset at a pinned URL, SHA-256 verified before anything is unpacked or run
//   ruleSet        a rule source at a pinned commit: only its included folders (a sparse, shallow fetch; no full clone
//                  is left on disk), the commit verified, files without a required licence header dropped, every rule
//                  file validated with the engine once, and the loadable ones cached once per machine. Rules are never
//                  copied into the application's repository.
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

const sh = (cmd, args, opts = {}) => spawnSync(cmd, args, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, timeout: (opts.timeoutSec ?? 600) * 1000, windowsHide: true, ...opts });
const hash = (s) => createHash('sha256').update(s).digest('hex');

function unpack(archive, dest, url) {
  fs.mkdirSync(dest, { recursive: true });
  if (/\.(tar\.gz|tgz)$/.test(url)) return sh('tar', ['-xzf', archive, '-C', dest]);
  // bsdtar (macOS, Windows 10+) reads zip archives; GNU tar does not, so Linux uses unzip.
  if (/\.zip$/.test(url)) return process.platform === 'linux' ? sh('unzip', ['-q', '-o', archive, '-d', dest]) : sh('tar', ['-xf', archive, '-C', dest]);
  return null;
}

// { ok, bin, detail }. `fetchImpl` is injectable (the test suite never downloads).
export async function installBinary(id, install, { cacheDir, plat, fetchImpl = globalThis.fetch }) {
  const d = install.platforms?.[plat];
  if (!d) return { ok: false, detail: `${id} ${install.version} has no build pinned for ${plat}` };
  // Keyed by the binary (install.name), not the tool entry: two entries running one engine share one copy.
  const dir = path.join(cacheDir, 'tools', `${install.name ?? id}-${install.version}-${plat}`);
  const bin = path.join(dir, d.bin);
  if (fs.existsSync(bin)) return { ok: true, bin, detail: `${id} ${install.version} already installed` };
  const stage = `${dir}.unpack-${process.pid}`;
  const archive = `${dir}.download-${process.pid}`;
  fs.mkdirSync(path.dirname(dir), { recursive: true });
  try {
    // A controller and a timer this call holds (an AbortSignal.timeout signal can be collected while the request waits).
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 600_000);
    let buf;
    try {
      const res = await fetchImpl(d.url, { redirect: 'follow', signal: ctl.signal });
      if (!res.ok) return { ok: false, detail: `${d.url}: HTTP ${res.status}` };
      buf = Buffer.from(await res.arrayBuffer());
    } finally {
      clearTimeout(timer);
    }
    const got = hash(buf);
    if (got !== d.sha256) return { ok: false, detail: `${id}: checksum mismatch for ${d.url} (expected ${d.sha256}, got ${got}); nothing was installed` };
    fs.writeFileSync(archive, buf);
    fs.rmSync(stage, { recursive: true, force: true });
    const r = unpack(archive, stage, d.url);
    if (r === null) {
      fs.mkdirSync(stage, { recursive: true });
      fs.copyFileSync(archive, path.join(stage, d.bin));
    } else if (r.status !== 0) return { ok: false, detail: `${id}: could not unpack ${path.basename(d.url)}: ${String(r.stderr).trim().slice(0, 300)}` };
    if (!fs.existsSync(path.join(stage, d.bin))) return { ok: false, detail: `${id}: ${d.bin} is not in ${path.basename(d.url)}` };
    if (process.platform !== 'win32') fs.chmodSync(path.join(stage, d.bin), 0o755);
    fs.rmSync(dir, { recursive: true, force: true });
    fs.renameSync(stage, dir);
    return { ok: true, bin, detail: `${id} ${install.version} installed (sha256 verified)` };
  } finally {
    fs.rmSync(archive, { force: true });
    fs.rmSync(stage, { recursive: true, force: true });
  }
}

// Where a pinned rule source lives in the cache: one folder per repository, commit and folder selection.
export const ruleSetDir = (cacheDir, src) => path.join(cacheDir, 'rules', `${src.id}-${String(src.commit).slice(0, 12)}-${hash(JSON.stringify([src.repo, src.commit, src.include ?? [], src.exclude ?? [], src.requireHeader ?? null])).slice(0, 10)}`);

const RULE_FILE = /\.ya?ml$/;
const walk = (dir) => (fs.existsSync(dir) ? fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(dir, e.name)) : [path.join(dir, e.name)])) : []);
const under = (rel, folders) => folders.some((f) => rel === f || rel.startsWith(`${f.replace(/\/$/, '')}/`));

// Fetches, filters and validates a pinned rule source. `validate(file) -> { ok, detail }` loads one rule file with the
// engine (null: no validation). Returns { ok, dir (the validated set), dropped: [{ file, why }], kept, detail }.
// The result is cached: a second call reads `<dir>/../ruleset.json`.
export function ruleSet(src, { cacheDir, validate = null, git = (args, cwd) => sh('git', args, { cwd }) }) {
  const root = ruleSetDir(cacheDir, src);
  const meta = path.join(root, 'ruleset.json');
  try {
    const m = JSON.parse(fs.readFileSync(meta, 'utf8'));
    if (m.commit === src.commit && fs.existsSync(m.dir)) return { ok: true, ...m, detail: `${src.id}@${src.commit.slice(0, 12)}: cached (${m.kept} rule file(s), ${m.dropped.length} dropped)` };
  } catch {
    /* not cached yet */
  }
  const include = src.include?.length ? src.include : null;
  const exclude = src.exclude ?? [];
  const tmp = `${root}.fetch-${process.pid}`;
  fs.rmSync(tmp, { recursive: true, force: true });
  fs.mkdirSync(tmp, { recursive: true });
  try {
    const steps = [['init', '-q'], ...(include ? [['sparse-checkout', 'set', '--no-cone', ...include.map((f) => `/${f.replace(/\/$/, '')}/`)]] : []), ['fetch', '-q', '--depth', '1', '--filter=blob:none', src.repo, src.commit], ['-c', 'advice.detachedHead=false', 'checkout', '-q', '--detach', 'FETCH_HEAD']];
    for (const args of steps) {
      const r = git(args, tmp);
      if (r.status !== 0) return { ok: false, detail: `${src.id}: could not fetch ${src.repo}@${src.commit.slice(0, 12)}: ${String(r.stderr).trim().slice(0, 300)}` };
    }
    const head = git(['rev-parse', 'HEAD'], tmp).stdout?.trim();
    if (head !== src.commit) return { ok: false, detail: `${src.id}: fetched ${head} where ${src.commit} is pinned` };
    const out = path.join(root, 'rules');
    fs.rmSync(root, { recursive: true, force: true });
    fs.mkdirSync(out, { recursive: true });
    const dropped = [];
    let kept = 0;
    for (const abs of walk(tmp)) {
      const rel = path.relative(tmp, abs).split(path.sep).join('/');
      if (rel.startsWith('.git/') || !RULE_FILE.test(rel)) continue;
      if (include && !under(rel, include)) continue;
      if (under(rel, exclude)) continue;
      const text = fs.readFileSync(abs, 'utf8');
      if (!/^\s*rules\s*:/m.test(text)) continue; // not a rule file (CI config, test data)
      if (src.requireHeader && !text.includes(src.requireHeader)) {
        dropped.push({ file: rel, why: `no "${src.requireHeader}" header (licence not stated in the file)` });
        continue;
      }
      const dest = path.join(out, rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, text);
      const v = validate ? validate(dest) : { ok: true };
      if (!v.ok) {
        fs.rmSync(dest, { force: true });
        dropped.push({ file: rel, why: `does not load: ${String(v.detail ?? '').slice(0, 300)}` });
        continue;
      }
      kept++;
    }
    const m = { id: src.id, repo: src.repo, commit: src.commit, include: include ?? [], exclude, licence: src.licence ?? null, dir: out, kept, dropped, ts: new Date().toISOString() };
    fs.writeFileSync(meta, `${JSON.stringify(m, null, 1)}\n`);
    return { ok: true, ...m, detail: `${src.id}@${src.commit.slice(0, 12)}: ${kept} rule file(s)${dropped.length ? `, ${dropped.length} dropped (${dropped.slice(0, 3).map((d) => d.file).join(', ')}${dropped.length > 3 ? ', ...' : ''})` : ''}` };
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

// A validator from an engine command template with {rule} and {empty} (an empty folder to scan): exit 0 loads.
export function commandValidator(argv, { cacheDir }) {
  const empty = path.join(cacheDir, 'empty');
  fs.mkdirSync(empty, { recursive: true });
  return (file) => {
    const a = argv.map((x) => x.replace(/\{rule\}/g, file).replace(/\{empty\}/g, empty));
    const r = sh(a[0], a.slice(1), { timeoutSec: 120 });
    return { ok: r.status === 0, detail: `exit ${r.status}${r.error ? ` (${r.error.message})` : ''}: ${`${r.stderr ?? ''}${r.stdout ?? ''}`.trim().split('\n').filter(Boolean).slice(-2).join(' ').slice(0, 300)}` };
  };
}

// After a tool's prepare step: data folders it must not keep (an advisory source under a non-commercial licence, or one
// the configuration turned off) are deleted wherever the tool put them under its cache, and listed. The tool then has
// no data for those ecosystems; what they would have covered is reported as not checked.
export function pruneData(cacheDir, data = []) {
  const names = new Set(data.filter((d) => d.excluded).flatMap((d) => d.paths ?? []).map((n) => n.toLowerCase()));
  if (!names.size) return [];
  const removed = [];
  const visit = (dir, depth) => {
    if (depth > 4 || !fs.existsSync(dir)) return;
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (!e.isDirectory()) continue;
      const p = path.join(dir, e.name);
      if (names.has(e.name.toLowerCase())) {
        fs.rmSync(p, { recursive: true, force: true });
        removed.push(p);
      } else visit(p, depth + 1);
    }
  };
  visit(cacheDir, 0);
  return removed;
}
